{"command": "cd ~; cat > ctl.py <<'EOF'
import workcell, math, sys, time
def call(*a):
    r=workcell.call(*a); return r
def step(dz,dx=0,dy=0):
    r=workcell.call("robot","step","right",str(dx),str(dy),str(dz),"--json"); return r.data["tcp_mm"][2], r.data["fz"]
def log(*a): print(*a, flush=True)
X0=float(sys.argv[1]) if len(sys.argv)>1 else 0.0
Y0=float(sys.argv[2]) if len(sys.argv)>2 else 60.0
ZS=104.0
pts=[(0,0)]
for ring in range(1,7):
    n=max(6,int(2*math.pi*ring/1.0))
    for k in range(n):
        a=2*math.pi*k/n; pts.append((round(ring*math.cos(a),1),round(ring*math.sin(a),1)))
found=None
for dx,dy in pts:
    x,y=X0+dx,Y0+dy
    call("robot","move","right",f"{x}",f"{y}",f"{ZS}")
    z=ZS; ok=True
    for i in range(9):
        z,f=step(-1)
        if f<-7: ok=False; break
    log(x,y,round(z,1),f,"IN" if ok else "")
    if ok:
        # confirm a few more mm with light force
        for i in range(5):
            z,f=step(-1)
            if f<-7: ok=False; break
        if ok: found=(x,y); break
    step(3)
log("found",found)
if found:
    for i in range(40):
        z,f=step(-1)
        if f<-7: break
    log("final z",z,f)
